% Star Model lab task graph and durable run-state projection.
% Runtime facts are append-only task_state/5 terms generated by scripts/lab.py.

:- dynamic task_state/5.

task(source_bundle).
task(codebase_corpus).
task(synthetic_reservoir).
task(dataset_validation).
task(dataset_manifest).
task(aws_stage).
task(aws_training).
task(pi_baseline_eval).
task(pi_candidate_eval).
task(comparison).
task(promotion_gate).

depends(dataset_validation, codebase_corpus).
depends(dataset_validation, synthetic_reservoir).
depends(dataset_manifest, dataset_validation).
depends(aws_stage, source_bundle).
depends(aws_stage, dataset_manifest).
depends(aws_training, aws_stage).
depends(pi_baseline_eval, dataset_manifest).
depends(pi_candidate_eval, aws_training).
depends(comparison, pi_baseline_eval).
depends(comparison, pi_candidate_eval).
depends(promotion_gate, comparison).

latest_state(Run, Task, State) :-
    findall(Timestamp-State0,
            task_state(Run, Task, State0, Timestamp, _Detail),
            Pairs),
    Pairs \= [],
    keysort(Pairs, Sorted),
    last(Sorted, _-State).

successful_state(done).
successful_state(skipped).

dependency_satisfied(Run, Dependency) :-
    latest_state(Run, Dependency, State),
    successful_state(State).

all_dependencies_satisfied(Run, Task) :-
    forall(depends(Task, Dependency),
           dependency_satisfied(Run, Dependency)).

unfinished(Run, Task) :-
    \+ (latest_state(Run, Task, State), successful_state(State)),
    \+ latest_state(Run, Task, running).

ready(Run, Task) :-
    task(Task),
    unfinished(Run, Task),
    all_dependencies_satisfied(Run, Task).

blocked(Run, Task, Dependency) :-
    task(Task),
    depends(Task, Dependency),
    \+ dependency_satisfied(Run, Dependency).

print_ready(Run) :-
    forall(ready(Run, Task), format('~w~n', [Task])).
